&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types de r&#244;deur&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_de_r&#244;deur_0&quot; href=&quot;#Les_arch&#233;types_de_r&#244;deur_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html&quot; title=&quot;Le r&#244;deur&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Archer-R&#244;deur-(R&#244;deur).html&quot; title=&quot;Archer r&#244;deur&quot;&gt;Archer r&#244;deur&lt;/a&gt; (&lt;i&gt;WMH&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arpenteur-Des-Profondeurs-(R&#244;deur).html&quot; title=&quot;Arpenteur des profondeurs&quot;&gt;Arpenteur des profondeurs&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Briseur-De-Guildes-(R&#244;deur).html&quot; title=&quot;Briseur de guildes&quot;&gt;Briseur de guildes&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Champion-Rebelle-(R&#244;deur).html&quot; title=&quot;Champion rebelle&quot;&gt;Champion rebelle&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Changeforme-(R&#244;deur).html&quot; title=&quot;Changeforme&quot;&gt;Changeforme&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-De-Troph&#233;es-(R&#244;deur).html&quot; title=&quot;Chasseur de troph&#233;es&quot;&gt;Chasseur de troph&#233;es&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-Sauvage-(R&#244;deur).html&quot; title=&quot;Chasseur sauvage&quot;&gt;Chasseur sauvage&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dandy-(R&#244;deur).html&quot; title=&quot;Dandy&quot;&gt;Dandy&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;claireur-De-Larm&#233;e-(R&#244;deur).html&quot; title=&quot;&#201;claireur de l&amp;#39;arm&#233;e&quot;&gt;&#201;claireur de l&#39;arm&#233;e&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fauconnier-(R&#244;deur).html&quot; title=&quot;Fauconnier&quot;&gt;Fauconnier&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Flibustier-(R&#244;deur).html&quot; title=&quot;Flibustier&quot;&gt;Flibustier&lt;/a&gt; (PMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gardien-(R&#244;deur).html&quot; title=&quot;Gardien&quot;&gt;Gardien&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gardien-Des-Vagues-(R&#244;deur).html&quot; title=&quot;Gardien des vagues&quot;&gt;Gardien des vagues&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Homme-Poisson-(Race).html&quot; title=&quot;Les hommes-poissons&quot;&gt;Homme-poisson&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guide-(R&#244;deur).html&quot; title=&quot;Guide&quot;&gt;Guide&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-B&#234;tes-(R&#244;deur).html&quot; title=&quot;Ma&#238;tre des b&#234;tes&quot;&gt;Ma&#238;tre des b&#234;tes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Messager-Secret-(R&#244;deur).html&quot; title=&quot;Messager secret&quot;&gt;Messager secret&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ombre-Sauvage-(R&#244;deur).html&quot; title=&quot;Ombre sauvage&quot;&gt;Ombre sauvage&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Demi-Elfe.html&quot; title=&quot;Les demi-elfes&quot;&gt;Demi-elfe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pisteur-Divin-(R&#244;deur).html&quot; title=&quot;Pisteur divin&quot;&gt;Pisteur divin&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur-Infiltr&#233;-(R&#244;deur).html&quot; title=&quot;R&#244;deur infiltr&#233;&quot;&gt;R&#244;deur infiltr&#233;&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur-Libre-Du-Nirmathas-(R&#244;deur).html&quot; title=&quot;R&#244;deur libre des for&#234;ts&quot;&gt;R&#244;deur libre des for&#234;ts&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur-Spirituel-(R&#244;deur).html&quot; title=&quot;R&#244;deur spirituel&quot;&gt;R&#244;deur spirituel&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur-Urbain-(R&#244;deur).html&quot; title=&quot;R&#244;deur urbain&quot;&gt;R&#244;deur urbain&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Seigneur-Des-Chevaux-(R&#244;deur).html&quot; title=&quot;Seigneur des chevaux&quot;&gt;Seigneur des chevaux&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sentinelle-(R&#244;deur).html&quot; title=&quot;Sentinelle&quot;&gt;Sentinelle&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tirailleur-(R&#244;deur).html&quot; title=&quot;Tirailleur&quot;&gt;Tirailleur&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Transporteur-(R&#244;deur).html&quot; title=&quot;Transporteur&quot;&gt;Transporteur&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Trappeur-(R&#244;deur).html&quot; title=&quot;Trappeur&quot;&gt;Trappeur&lt;/a&gt; (UM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Traqueur-Du-Cr&#233;puscule-(R&#244;deur).html&quot; title=&quot;Traqueur du cr&#233;puscule&quot;&gt;Traqueur du cr&#233;puscule&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Fetchelin-(Race).html&quot; title=&quot;Les fetchelins&quot;&gt;Fetchelin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Traqueur-Sauvage-(R&#244;deur).html&quot; title=&quot;Traqueur sauvage&quot;&gt;Traqueur sauvage&lt;/a&gt; (UC)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - R&#232;gles avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Player&#39;s Guide/Manuel des joueurs - R&#232;gles avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAPG.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;La plupart des r&#244;deurs s’aventurent dans les contr&#233;es sauvages mais certains laissent aussi l’aspect sauvage de ces contr&#233;es p&#233;n&#233;trer en eux. Suite &#224; une mal&#233;diction, une maladie, un rituel ancien, une l&#233;g&#232;re influence lycanthropique parmi ses a&#239;eux ou l’influence corruptrice du Chaos, ces r&#244;deurs laissent libre cours &#224; leur c&#244;t&#233; sauvage pour se transformer en des cr&#233;atures primitives et brutales. Les changeformes suscitent souvent l’&#233;merveillement mais aussi la peur.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;Un changeforme poss&#232;de les aptitudes de classe suivantes :&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Don de style de combat (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Don_de_style_de_combat_Ext_0&quot; href=&quot;#Don_de_style_de_combat_Ext_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 2, le changeforme doit choisir le &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#DONDESTYLEDECOMBAT&quot; title=&quot;Le r&#244;deur&quot;&gt;style de combat&lt;/a&gt; &lt;i&gt;arme naturelle&lt;/i&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Talent du changeforme (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Talent_du_changeforme_Sur_1&quot; href=&quot;#Talent_du_changeforme_Sur_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 3, le changeforme peut prendre l’aspect d’une cr&#233;ature sauvage une fois par jour par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt;. Il peut rester dans cette forme pendant un nombre de rounds &#233;gal &#224; son niveau de r&#244;deur + son modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;La Sagesse&quot;&gt;Sagesse&lt;/a&gt;. Tant qu’il a l’aspect d’une de ces formes, le r&#244;deur gagne le &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-M&#233;tamorphe.html&quot; title=&quot;M&#233;tamorphe (sous-type)&quot;&gt;sous-type m&#233;tamorphe&lt;/a&gt;. Le changeforme doit choisir l’une des formes suivantes. Une fois ce choix effectu&#233;, il ne peut plus &#234;tre modifi&#233;.
&lt;ul&gt;&lt;li&gt;&lt;i&gt;Forme de l’aigle.&lt;/i&gt; La peau du r&#244;deur s’&#233;tend, son nez devient crochu et ses yeux s’agrandissent. Dans cette forme, le r&#244;deur gagne un bonus de +10 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;i&gt;Forme de l’ours.&lt;/i&gt; Les muscles du r&#244;deur deviennent plus puissants et plus tendus et son visage se rapproche de celui d’un ours. Dans cette forme, le r&#244;deur gagne un bonus d’alt&#233;ration de +4 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; mais sa vitesse de d&#233;placement de base se r&#233;duit &#224; 6 m&#232;tres (4 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;).&lt;/li&gt;&lt;li&gt;&lt;i&gt;Forme de la loutre.&lt;/i&gt; Les mains et les pieds du r&#244;deur deviennent palm&#233;s et son corps se recouvre d’un pelage huileux r&#233;sistant &#224; l’eau. Dans cette forme, le r&#244;deur gagne une vitesse de nage de 9 m&#232;tres (6 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) et un bonus de +8 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Natation.html&quot; title=&quot;Natation&quot;&gt;Natation&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;i&gt;Forme du chacal.&lt;/i&gt; Le r&#244;deur s’amincit et devient hyperactif, avec des mouvements plus nerveux. Dans cette forme, le r&#244;deur peut utiliser une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;action de mouvement&lt;/a&gt; pour se d&#233;placer de la moiti&#233; de sa &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Vitessededeplacement.html&quot; title=&quot;VD&quot;&gt;vitesse de d&#233;placement&lt;/a&gt; de base sans provoquer d’&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;attaque d&amp;#39;opportunit&#233;&quot;&gt;attaque d’opportunit&#233;&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;i&gt;Forme du dragon.&lt;/i&gt; La peau du r&#244;deur devient rugueuse et se recouvre d’&#233;cailles. Dans cette forme, le r&#244;deur gagne un bonus d’armure naturelle de +2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;i&gt;Forme du f&#233;lin.&lt;/i&gt; Les muscles du r&#244;deur deviennent plus souples et mieux d&#233;finis et sa d&#233;marche plus gracieuse et contr&#244;l&#233;e. Dans cette forme, le r&#244;deur voit sa &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Vitessededeplacement.html&quot; title=&quot;VD&quot;&gt;vitesse de d&#233;placement&lt;/a&gt; de base augmenter de 3 m&#232;tres (2 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) et il gagne un bonus de +4 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; et d’&lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;Au niveau 8 et tous les cinq niveaux par la suite, le r&#244;deur peut choisir une forme suppl&#233;mentaire pour son talent de changeforme et il peut utiliser cette capacit&#233; une fois de plus chaque jour. Ce n’est pas un effet de m&#233;tamorphose. Un r&#244;deur adoptant une des formes autoris&#233;es par sa capacit&#233; de talent du changeforme peut encore &#234;tre affect&#233; par une capacit&#233; de m&#233;tamorphose tout en conservant les bonus et traits que cette forme lui donne. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#ENVIRONNEMENTDEPREDILECTION&quot; title=&quot;Le r&#244;deur&quot;&gt;Environnement de pr&#233;dilection&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Forme duale (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Forme_duale_Ext_2&quot; href=&quot;#Forme_duale_Ext_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 12, lorsque le changeforme utilise son talent de changeforme, il peut adopter un aspect hybride m&#233;langeant deux de ses formes. Il gagne les bonus de ces deux formes. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#CAMOUFLAGE&quot; title=&quot;Le r&#244;deur&quot;&gt;Camouflage&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Ma&#238;tre changeforme (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Ma&#238;tre_changeforme_Sur_3&quot; href=&quot;#Ma&#238;tre_changeforme_Sur_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 20, le talent de changeforme du r&#244;deur se d&#233;veloppe et il peut adopter les formes v&#233;ritables des cr&#233;atures imit&#233;es. Le r&#244;deur peut encore utiliser sa capacit&#233; de forme duale mais il ne peut pas b&#233;n&#233;ficier de plus d’un effet de m&#233;tamorphose &#224; la fois. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#MAITRECHASSEUR&quot; title=&quot;Le r&#244;deur&quot;&gt;Ma&#238;tre chasseur&lt;/a&gt;. Les formes auxquelles le r&#244;deur a acc&#232;s gr&#226;ce &#224; son talent de changeforme s’am&#233;liorent comme indiqu&#233; ci-dessous.
&lt;ul&gt;&lt;li&gt;&lt;i&gt;Forme de l’aigle.&lt;/i&gt; La peau du r&#244;deur s’&#233;tend, son nez devient crochu et ses yeux s’agrandissent. Dans cette forme, le r&#244;deur gagne un bonus de +10 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; et une vitesse de vol de 12 m&#232;tres (9 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) avec une bonne manœuvrabilit&#233;. Au lieu de cela, le r&#244;deur peut se m&#233;tamorphoser en aigle ou en rapace similaire comme s’il avait lanc&#233; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-Bestiale-Iv.html&quot; title=&quot;Forme bestiale IV&quot;&gt;forme bestiale IV&lt;/a&gt;&lt;/i&gt;.&lt;/li&gt;&lt;li&gt;&lt;i&gt;Forme de l’ours.&lt;/i&gt; Les muscles du r&#244;deur deviennent plus puissants et plus tendus et son visage se rapproche de celui d’un ours. Dans cette forme, le r&#244;deur gagne un bonus d’alt&#233;ration de +8 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; sans voir sa &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Vitessededeplacement.html&quot; title=&quot;VD&quot;&gt;vitesse de d&#233;placement&lt;/a&gt; se r&#233;duire. Au lieu de cela, le r&#244;deur peut se m&#233;tamorphoser en ours comme s’il avait lanc&#233; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-Bestiale-Iv.html&quot; title=&quot;Forme bestiale IV&quot;&gt;forme bestiale IV&lt;/a&gt;&lt;/i&gt;.&lt;/li&gt;&lt;li&gt;&lt;i&gt;Forme de la loutre.&lt;/i&gt; Les mains et les pieds du r&#244;deur deviennent palm&#233;s et son corps se recouvre d’un pelage huileux r&#233;sistant &#224; l’eau. Dans cette forme, le r&#244;deur gagne une vitesse de nage de 18 m&#232;tres (12 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) et un bonus de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Natation.html&quot; title=&quot;Natation&quot;&gt;Natation&lt;/a&gt;. Au lieu de cela, le r&#244;deur peut se m&#233;tamorphoser en loutre ou en mammif&#232;re aquatique similaire comme s’il avait lanc&#233; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-Bestiale-Iv.html&quot; title=&quot;Forme bestiale IV&quot;&gt;forme bestiale IV&lt;/a&gt;&lt;/i&gt;.&lt;/li&gt;&lt;li&gt;&lt;i&gt;Forme du chacal.&lt;/i&gt; Le r&#244;deur s’amincit et devient hyperactif, avec des mouvements plus nerveux. Dans cette forme, les d&#233;placements du r&#244;deur ne provoquent aucune &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;attaque d&amp;#39;opportunit&#233;&quot;&gt;attaque d’opportunit&#233;&lt;/a&gt;. Au lieu de cela, le r&#244;deur peut se m&#233;tamorphoser en chacal ou en un autre canid&#233; comme s’il avait lanc&#233; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-Bestiale-Iv.html&quot; title=&quot;Forme bestiale IV&quot;&gt;forme bestiale IV&lt;/a&gt;&lt;/i&gt;.&lt;/li&gt;&lt;li&gt;&lt;i&gt;Forme du dragon.&lt;/i&gt; La peau du r&#244;deur devient rugueuse et se recouvre d’&#233;cailles. Dans cette forme, le r&#244;deur gagne un bonus d’armure naturelle de +4 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; et une vitesse de vol de 9 m&#232;tres (6 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) avec une manœuvrabilit&#233; moyenne. Au lieu de cela, le r&#244;deur peut se m&#233;tamorphoser en dragon comme s’il avait lanc&#233; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-Draconique-I.html&quot; title=&quot;Forme draconique I&quot;&gt;forme draconique I&lt;/a&gt;&lt;/i&gt;.&lt;/li&gt;&lt;li&gt;&lt;i&gt;Forme du f&#233;lin.&lt;/i&gt; Les muscles du r&#244;deur deviennent plus souples et mieux d&#233;finis et sa d&#233;marche plus gracieuse et contr&#244;l&#233;e. Dans cette forme, le r&#244;deur voit sa &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Vitessededeplacement.html&quot; title=&quot;VD&quot;&gt;vitesse de d&#233;placement&lt;/a&gt; de base augmenter de 6 m&#232;tres (4 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) et il gagne un bonus de +10 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; et d’&lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt;. Au lieu de cela, le r&#244;deur peut se m&#233;tamorphoser en f&#233;lin de n’importe quelle taille comme s’il avait lanc&#233; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-Bestiale-Iv.html&quot; title=&quot;Forme bestiale IV&quot;&gt;forme bestiale IV&lt;/a&gt;&lt;/i&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;
